{"thought":"I found Riverside-related schools. Now I need to calculate the average SAT math score per district and filter for those exceeding 400. Then I'll list the school names and funding types for schools in those qualifying districts.","action":"execute_python","action_input":{"code":"import sqlite3
import csv
from collections import defaultdict

# Get Riverside-related schools with their CDS and funding
riverside_schools = {}
with open('csv/frpm.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        district_name = row.get('District Name', '').strip()
        county_name = row.get('County Name', '').lower()
        if 'riverside' in district_name.lower() or 'riverside' in county_name:
            cds = row.get('CDSCode', '')
            school_name = row.get('School Name', '')
            district = district_name
            funding = row.get('Charter Funding Type', '').strip() or row.get('District Type', '').strip()
            riverside_schools[cds] = {'school_name': school_name, 'district': district, 'funding': funding}

print(f'Found {len(riverside_schools)} Riverside-related schools')

# Calculate average SAT math per district
conn = sqlite3.connect('db/satscores.db')
cursor = conn.cursor()

district_sat_scores = defaultdict(list)
for cds, data in riverside_schools.items():
    district = data['district']
    cursor.execute('SELECT AvgScrMath FROM satscores WHERE cds = ? AND AvgScrMath IS NOT NULL', (cds,))
    result = cursor.fetchone()
    if result:
        district_sat_scores[district].append(result[0])

# Calculate average SAT math per district
avg_sat_per_district = {}
for district, scores in district_sat_scores.items():
    if scores:
        avg_sat_per_district[district] = sum(scores) / len(scores)

# Find districts with average SAT math > 400
qualifying_districts = {d for d, avg in avg_sat_per_district.items() if avg > 400}
print(f'Qualifying districts (avg SAT math > 400): {qualifying_districts}')

# List schools from those districts
result_rows = []
for cds, data in riverside_schools.items():
    if data['district'] in qualifying_districts:
        result_rows.append([data['school_name'], data['funding']])

print(f'Total schools in qualifying districts: {len(result_rows)}')
for r in result_rows[:10]:
    print(r)

conn.close()"}}
```

